const D = params.diameter;
const R = D * 0.5;
const tilt = params.tilt;
const depth = D * 0.18;
const thick = D * 0.018;
const pivotY = D * 0.68;
const rad = tilt * Math.PI / 180;
const structure = { preset: 'metal', color: params.color, metalness: 0.45, roughness: 0.38, flatShading: true };
const darkMetal = { preset: 'metal', color: '#343b42', metalness: 0.75, roughness: 0.3 };
const concrete = { preset: 'concrete', color: '#8b8f91', roughness: 0.92, flatShading: true };
const accent = { preset: 'metal', color: '#d9822b', metalness: 0.55, roughness: 0.35 };
function dishPoint(r, a, extra) {
  const y = -depth + depth * (r * r) / (R * R) + extra;
  const x0 = Math.cos(a) * r;
  const z0 = Math.sin(a) * r;
  return [x0 * Math.cos(rad) - y * Math.sin(rad), pivotY + x0 * Math.sin(rad) + y * Math.cos(rad), z0];
}
function axisPoint(y) {
  return [-y * Math.sin(rad), pivotY + y * Math.cos(rad), 0];
}
const profile = [];
for (let i = 0; i <= 10; i++) {
  const r = R * i / 10;
  profile.push([r, -depth - thick + depth * (r * r) / (R * R)]);
}
profile.push([R, thick * 0.35]);
for (let i = 10; i >= 0; i--) {
  const r = R * i / 10;
  profile.push([r, -depth + depth * (r * r) / (R * R)]);
}
const reflector = api.lathe(profile, 32).rotate(0, 0, tilt).translate(0, pivotY, 0);
reflector.vertexColor((x, y, z) => api.mix(params.color, '#ffffff', 0.08 + 0.07 * api.noise3(x * 0.7, y * 0.7, z * 0.7)));
api.add(reflector, { preset: 'metal', metalness: 0.32, roughness: 0.46, flatShading: true });
const rim = api.torus(R, thick * 0.85).rotate(90, 0, 0).rotate(0, 0, tilt).translate(0, pivotY, 0);
api.add(rim, structure);
for (let k = 0; k < 12; k++) {
  const a = k * Math.PI * 2 / 12;
  const path = [];
  for (let j = 1; j <= 8; j++) path.push(dishPoint(R * j / 8, a, -thick * 1.15));
  api.add(api.tube(path, thick * 0.38, 6), darkMetal);
}
const rearHub = dishPoint(0, 0, -thick * 2.2);
api.add(api.sphere(D * 0.055, 1).translate(rearHub[0], rearHub[1], rearHub[2]), darkMetal);
const focusDist = D * 0.52;
const feed = axisPoint(focusDist);
const feedBack = axisPoint(focusDist - D * 0.09);
api.add(api.tube([feedBack, feed], D * 0.035, 10), darkMetal);
api.add(api.cone(D * 0.075, D * 0.13, 12).rotate(0, 0, tilt + 180).translate(feed[0], feed[1], feed[2]), accent);
for (let k = 0; k < 3; k++) {
  const a = k * Math.PI * 2 / 3;
  const edge = dishPoint(R * 0.78, a, thick * 0.8);
  api.add(api.tube([edge, feedBack], D * 0.018, 6), structure);
}
const baseR = D * 0.22;
api.add(api.cylinder(baseR * 1.18, baseR * 1.32, D * 0.16, 20).translate(0, D * 0.08, 0), concrete);
api.add(api.cylinder(baseR, baseR * 1.08, D * 0.32, 18).translate(0, D * 0.32, 0), concrete);
api.add(api.cylinder(baseR * 0.83, baseR * 0.83, D * 0.08, 18).translate(0, D * 0.52, 0), darkMetal);
const axleLen = D * 0.36;
api.add(api.cylinder(D * 0.075, D * 0.075, axleLen, 14).rotate(90, 0, 0).translate(0, pivotY, 0), darkMetal);
for (let side = -1; side <= 1; side += 2) {
  const z = side * D * 0.18;
  const leg = api.tube([[0, D * 0.52, z], [0, pivotY, z]], D * 0.045, 8);
  api.add(leg, structure);
  api.add(api.cylinder(D * 0.105, D * 0.105, D * 0.07, 14).rotate(90, 0, 0).translate(0, pivotY, z), accent);
}
api.add(api.box(D * 0.22, D * 0.14, D * 0.16).translate(baseR * 0.92, D * 0.4, 0), darkMetal);
api.add(api.cylinder(D * 0.035, D * 0.035, D * 0.18, 10).translate(baseR * 1.02, D * 0.58, 0), accent);
api.collider({ kind: 'cylinder', radius: baseR * 1.32, halfHeight: D * 0.26, offset: [0, D * 0.26, 0] });
api.collider({ kind: 'sphere', radius: R, offset: [0, pivotY, 0] });
return api.build();
